import { FP, idiv, seconds, tiles, tilesPerSecond } from './math.ts';
import type { ActiveSkill, BonusKey, EntityDef, RaceId, TeamId, Weapon, ZoneKind } from './types.ts';

// ── 맵 상수 ────────────────────────────────────────────────────────────────
export const MAP = {
  /** FP 단위 전장 길이 (x: 0 ~ LENGTH). */
  LENGTH: tiles(96),
  /** FP 단위 레인 반폭 (y: -HALF_W ~ +HALF_W). */
  HALF_W: tiles(7),

  /** 팀별 구조물/스폰 x 좌표. 인덱스 = TeamId. */
  NEXUS_X: [tiles(4), tiles(92)] as const,
  TOWER_X: [tiles(24), tiles(72)] as const,
  SPAWN_X: [tiles(13), tiles(83)] as const,

  /** 슬롯별 스폰 y 밴드 중심. */
  SLOT_Y: [tiles(-4.5), tiles(0), tiles(4.5)] as const,

  PREP_TICKS: seconds(60),
  WAVE_TICKS: seconds(60),

  INCOME_INTERVAL: seconds(5),
  INCOME_BASE: 30,
  INCOME_PER_LEVEL: 8,
  INCOME_UPGRADE_BASE_COST: 200,
  INCOME_UPGRADE_COST_PER_LEVEL: 75,
  /** 인컴 업그레이드 최대 레벨. */
  INCOME_MAX_LEVEL: 8,
  /** 인컴 업그레이드 후 재구매 대기 시간 (틱). */
  INCOME_COOLDOWN: seconds(60),
  START_MONEY: 250,

  /**
   * 수호탑 파괴 보상: 부순 팀의 "전원"이 각각 받는다.
   * 탑을 내주고 인컴·테크만 올리는 그리드 전략의 카운터웨이트.
   */
  TOWER_BOUNTY: 350,

  /**
   * 수호자(중간보스) 격파 보상. 넥서스 보호막을 벗기는 관문이라 탑과 같은 값을 준다.
   * 관문을 뚫은 팀이 마무리 화력을 살 자금을 확보하게 하는 장치.
   */
  GUARDIAN_BOUNTY: 350,

  /** 테크 연구 소요 시간 (틱). 누른 뒤 이 시간이 지나야 해금된다. */
  TECH_TIME: seconds(60),
  /** 테크 4 연구는 유난히 오래 걸린다 (3분) — 최종 유닛으로 가는 마지막 관문. */
  TECH_TIME_T4: seconds(180),
  /** 테크업 비용. 인덱스 = 현재 레벨 (1→2 는 [0], 2→3 은 [1]). 잠정치. */
  TECH_UP_COST: [300, 600, 1800] as const,
  TECH_MAX: 4,
} as const;

export function incomeUpgradeCost(level: number): number {
  return MAP.INCOME_UPGRADE_BASE_COST + MAP.INCOME_UPGRADE_COST_PER_LEVEL * level;
}
// ── 맵 정의 (지오메트리) ───────────────────────────────────────────────────
// 전장은 "중앙선 폴리라인 + 반폭" 코리도어다. 유닛은 중앙선을 따라 진군하고
// y 는 중앙선 ± halfW 로 제한된다. 직선 맵은 중앙선이 y=0 인 특수 케이스.

export interface MapDef {
  readonly id: string;
  readonly name: string;
  readonly length: number; // FP
  readonly halfW: number; // FP, 코리도어 반폭
  /** 중앙선 폴리라인 [x, y][] (x 오름차순, FP). 구간은 선형 보간. */
  readonly center: readonly (readonly [number, number])[];
  /**
   * 수직 가지 길 (Y자형 맵): x 고정, y0~y1 구간의 코리도어 (폭 = halfW).
   * 12시 방향처럼 메인 레인에 수직으로 붙는 길. 유닛 통행·타일 렌더 모두 인식한다.
   */
  readonly branches?: readonly { readonly x: number; readonly y0: number; readonly y1: number; readonly halfW?: number }[];
  /**
   * 좁은 입구(초크 포인트): x 구간의 레인 반폭 오버라이드.
   * 수비하기 좋은 병목 — 적이 좁은 길을 비집고 들어온다.
   */
  readonly chokes?: readonly { readonly x0: number; readonly x1: number; readonly halfW: number }[];
  /**
   * 화면을 90도 돌려 그린다 (세로 맵). 시뮬은 그대로 x축 진행이지만,
   * 렌더에서 진행 방향을 위쪽으로 세운다 — 6시에서 12시로 올라가는 그림.
   */
  readonly vertical?: boolean;
  /**
   * 지형 배경 그림 (타일 오토타일링 대신 한 장을 통째로 깐다).
   * 손으로 그린 지형을 그대로 쓰는 맵용. 월드 크기에 맞춰 늘어난다.
   */
  readonly bgImage?: string;
  /**
   * 격자 통행 마스크 — 손으로 그린 지형에서 「다닐 수 있는 칸」을 그대로 옮긴 것.
   * data 는 rows x cols 문자열('.' 통행 가능 / '#' 막힘). 행 0 = 진행축 시작(내 진영),
   * 열 0 = y 가 가장 작은 쪽. 지형 그림에서 자동 생성한다.
   */
  readonly mask?: { readonly cols: number; readonly rows: number; readonly data: string };
  /**
   * 플레이어가 고른 출정 갈래를 끝까지 유지시키는 중간 경유지.
   * laneY 는 deployLaneY 와 정확히 대응하고, x/y 를 지난 뒤 공용 흐름장으로 합류한다.
   */
  readonly deployWaypoints?: readonly {
    readonly laneY: number;
    readonly x: number;
    readonly y: number;
  }[];
  /**
   * 가운데가 갈라진 구간 — 두 갈래 길 사이에 통행 불가 지대(호수 등)를 둔다.
   * x0~x1 구간에서 |y| < gap 은 지형이 아니다. 유닛은 좌우 어느 쪽 길에 있느냐로
   * 갈리며, 비행도 넘지 못한다 (지형 자체가 없는 것으로 친다).
   */
  readonly splits?: readonly { readonly x0: number; readonly x1: number; readonly gap: number }[];
  /**
   * 지형 해저드 — 맵에 처음부터 깔려 있는 장판 (진흙길·덩굴길).
   *
   * 스킬 장판과 같은 구조를 쓰되 team 2(중립적대)로 깔아 **양 진영 모두**에게
   * 걸린다. 지상 전용이라 비행은 그냥 지나간다 — 「하늘을 사야 하는 이유」를
   * 지형이 한 번 더 설명하는 셈.
   */
  readonly terrain?: readonly {
    readonly kind: ZoneKind;
    readonly x: number;
    readonly y: number;
    readonly radius: number;
  }[];
  readonly nexusX: readonly [number, number];
  readonly towerX: readonly [number, number];
  readonly spawnX: readonly [number, number];
  /**
   * 넥서스 자리를 (x, y) 로 직접 지정한다 — 손그림 지형에서 진영이 코리도어
   * 한복판이 아니라 「구석 언덕 위」에 있는 맵용 (5 올빼미 성채).
   *
   * 보통은 nexusX 하나만 주고 y 는 laneCenterY 가 정하지만, 그러면 진영이
   * 반드시 폭의 한가운데에 놓인다. 언덕이 좌우 끝에 있으면 그 규약이 안 맞는다.
   * 지정하면 nexusX 대신 이 좌표를 쓴다 (nexusX 는 흐름장 목표로 계속 쓰인다).
   */
  readonly nexusPos?: readonly [readonly [number, number], readonly [number, number]];
  /** 출정 위치를 (x, y) 로 직접 지정 — nexusPos 와 같은 이유. */
  readonly spawnPos?: readonly [readonly [number, number], readonly [number, number]];
}

