export const DEFAULT_MAP = 'plains';

/** x 위치에서의 중앙선 y (선형 보간, 정수). */
export function laneCenterY(m: MapDef, x: number): number {
  const pts = m.center;
  if (x <= pts[0]![0]) return pts[0]![1];
  for (let i = 1; i < pts.length; i++) {
    const [x1, y1] = pts[i]!;
    if (x <= x1) {
      const [x0, y0] = pts[i - 1]!;
      if (x1 === x0) return y1;
      return y0 + idiv((y1 - y0) * (x - x0), x1 - x0);
    }
  }
  return pts[pts.length - 1]![1];
}

/** 맵의 세로 반높이 (중앙선 최대 이탈 + 반폭). 렌더/클램프 경계용. */
/**
 * 이 지점을 밟을 수 있는가 (격자 마스크가 있는 맵만). 마스크가 없으면 언제나 true —
 * 그런 맵은 기존 「중앙선 ± 폭」 규칙을 따른다.
 */
/**
 * 벽까지의 거리(칸) — 벽 칸 전부를 씨앗으로 놓은 BFS.
 * 「길 한복판이 어디인가」를 알아야 부대를 절벽에서 떼어 놓을 수 있다.
 */
const wallDistCache = new Map<string, Int32Array>();

function wallDistOf(m: MapDef): Int32Array {
  const hit = wallDistCache.get(m.id);
  if (hit) return hit;
  const { cols, rows, data } = m.mask!;
  const dist = new Int32Array(cols * rows).fill(-1);
  const queue: number[] = [];
  for (let i = 0; i < cols * rows; i++) {
    // 맵 밖도 벽이다 — 가장자리 칸은 처음부터 1로 잡힌다
    if (data.charCodeAt(i) !== 46) { dist[i] = 0; queue.push(i); }
  }
  for (let qi = 0; qi < queue.length; qi++) {
    const i = queue[qi]!;
    const r = (i / cols) | 0;
    const c = i - r * cols;
    const d = dist[i]! + 1;
    for (const n of [
      r > 0 ? i - cols : -1,
      r < rows - 1 ? i + cols : -1,
      c > 0 ? i - 1 : -1,
      c < cols - 1 ? i + 1 : -1,
    ]) {
      if (n < 0 || dist[n] !== -1) continue;
      dist[n] = d;
      queue.push(n);
    }
  }
  // 맵 가장자리에 붙은 길 칸은 이웃이 없어 -1 로 남는다 — 벽에 닿은 것으로 친다
  for (let i = 0; i < cols * rows; i++) if (dist[i] === -1) dist[i] = 1;
  wallDistCache.set(m.id, dist);
  return dist;
}

/**
 * 「벽에서 이만큼 떨어지면 더는 값을 안 얹는다」는 기준 (칸).
 *
 * 순수 BFS 는 최단거리라 굽은 길에서 안쪽 벽을 타고 돈다 — 실제로 5스테이지
 * 부대가 절벽에 딱 붙어 행군했다. 벽에 가까운 칸에 통행 비용을 얹으면 거리가
 * 비슷할 때 길 한복판으로 걷는다. 마스크 해상도는 맵마다 다르므로(타일당 2칸·
 * 4칸) 칸이 아니라 「1.5타일」로 잡는다.
 */
function hugNearOf(m: MapDef): number {
  const cellsPerTile = idiv(m.mask!.rows * FP, m.length);
  const near = idiv(cellsPerTile * 3, 2);
  return near < 1 ? 1 : near;
}

/**
 * 다이얼(버킷) 다익스트라. 간선 비용이 1..near 로 좁아 우선순위 큐가 필요 없다 —
 * 정수 연산 + 고정 순회 순서라 결정론이 유지된다.
 *
 * near = 0 이면 비용 없이 걸음 수만 세는 순수 BFS 가 된다.
 */
function dialField(m: MapDef, seeds: readonly number[], near: number): Int32Array {
  const { cols, rows, data } = m.mask!;
  const dist = new Int32Array(cols * rows).fill(-1);
  const wd = near > 0 ? wallDistOf(m) : null;
  const MAXW = near > 0 ? near : 1;
  const buckets: number[][] = [];
  for (let b = 0; b <= MAXW; b++) buckets.push([]);
  for (const s of seeds) {
    if (s < 0 || s >= cols * rows || dist[s] !== -1) continue;
    dist[s] = 0;
    buckets[0]!.push(s);
  }
  // 최대 거리 상한 — 무한 루프 방지용 안전핀 (정상적으로는 훨씬 먼저 끝난다)
  const LIMIT = cols * rows * (MAXW + 1) + MAXW + 2;
  for (let base = 0; base < LIMIT; base++) {
    const bk = buckets[base % (MAXW + 1)]!;
    if (bk.length === 0) {
      let any = false;
      for (const q of buckets) if (q.length > 0) { any = true; break; }
      if (!any) break;
      continue;
    }
    const cur = bk.slice();
    bk.length = 0;
    for (const i of cur) {
      if (dist[i]! !== base) continue;   // 더 짧은 값으로 이미 확정됨
      const r = (i / cols) | 0;
      const c = i - r * cols;
      // 상하좌우 (대각선 없음 — 벽 모서리를 통과하지 않게)
      for (const n of [
        r > 0 ? i - cols : -1,
        r < rows - 1 ? i + cols : -1,
        c > 0 ? i - 1 : -1,
        c < cols - 1 ? i + 1 : -1,
      ]) {
        if (n < 0 || data.charCodeAt(n) !== 46) continue;
        let extra = 0;
        if (wd) {
          const gap = near - wd[n]!;
          if (gap > 0) extra = gap;
        }
        const nd = base + 1 + extra;
        if (dist[n] !== -1 && dist[n]! <= nd) continue;
        dist[n] = nd;
        buckets[nd % (MAXW + 1)]!.push(n);
      }
    }
  }
  return dist;
}

/** 팀별 목적지 씨앗 칸 (상대 진영 자리). */
function goalSeedsOf(m: MapDef, team: number): number[] {
  const { cols, rows, data } = m.mask!;
  const seeds: number[] = [];
  // 목적지 = 상대 넥서스가 선 자리. 맵 끝 줄은 대개 숲이라 그걸 쓰면 씨앗이 없다.
  const goalX = team === 0 ? m.nexusX[1] : m.nexusX[0];
  const goalRow = Math.max(0, Math.min(rows - 1, idiv(goalX * rows, m.length)));
  const gp = m.nexusPos?.[team === 0 ? 1 : 0];
  if (gp) {
    /*
     * 진영이 폭의 한복판이 아니라 구석 언덕 위에 있는 맵 (5 올빼미 성채).
     *
     * 목표 「줄 전체」를 씨앗으로 깔면 같은 높이의 반대편 산길까지 목적지가
     * 돼서, 적 지상 부대가 우리 언덕 대신 건너편 길에 멈춰 선다.
     * nexusPos 가 있으면 그 자리 둘레만 씨앗으로 쓴다.
     */
    const gr = Math.max(0, Math.min(rows - 1, idiv(gp[0] * rows, m.length)));
    const halfH = mapHalfH(m);
    const gc = Math.max(0, Math.min(cols - 1, idiv((gp[1] + halfH) * cols, halfH * 2)));
    for (let rad = 2; rad <= 12 && seeds.length === 0; rad += 2) {
      for (let r = gr - rad; r <= gr + rad; r++) {
        if (r < 0 || r >= rows) continue;
        for (let c = gc - rad; c <= gc + rad; c++) {
          if (c < 0 || c >= cols) continue;
          const i = r * cols + c;
          if (data.charCodeAt(i) === 46) seeds.push(i);
        }
      }
    }
  }
  for (let dr = 0; dr <= 3 && seeds.length === 0; dr++) {
    for (const r of dr === 0 ? [goalRow] : [goalRow - dr, goalRow + dr]) {
      if (r < 0 || r >= rows) continue;
      for (let c = 0; c < cols; c++) {
        const i = r * cols + c;
        if (data.charCodeAt(i) === 46) seeds.push(i);
      }
    }
  }
  return seeds;
}

/**
 * 격자 마스크 맵의 「흐름장」 — 각 칸에서 목적지까지의 통행 비용.
 * 맵마다 팀별로 한 번만 계산해 두고, 유닛은 값이 줄어드는 이웃으로 걸어간다.
 * 중앙선을 따라가는 방식은 길이 굽으면 벽을 향해 걷다 끼기 때문에 이걸 쓴다.
 *
 * 값은 걸음 수가 아니라 「비용」이다 — 벽에 붙은 칸이 비싸다(hugNearOf).
 * 거리를 재야 할 때는 maskStepsOf 를 쓴다.
 *
 * 결정론: 정수 BFS + 고정 순회 순서. 같은 맵이면 언제나 같은 결과.
 */
const flowCache = new Map<string, Int32Array[]>();

export function flowFieldOf(m: MapDef): Int32Array[] | null {
  const mk = m.mask;
  if (!mk) return null;
  const hit = flowCache.get(m.id);
  if (hit) return hit;
  const near = hugNearOf(m);
  const fields = [0, 1].map((team) => dialField(m, goalSeedsOf(m, team), near));
  flowCache.set(m.id, fields);
  return fields;
}

/**
 * 같은 목적지까지의 「걸음 수」 (통행 비용 없이).
 * 흐름장 값은 벽 회피 비용이 섞여 있어 거리로 못 쓴다 — 지형 계약 검증
 * (「지상 몇 타일 / 비행 몇 타일」)은 이쪽을 봐야 한다.
 */
const stepCache = new Map<string, Int32Array[]>();

export function maskStepsOf(m: MapDef): Int32Array[] | null {
  if (!m.mask) return null;
  const hit = stepCache.get(m.id);
  if (hit) return hit;
  const fields = [0, 1].map((team) => dialField(m, goalSeedsOf(m, team), 0));
  stepCache.set(m.id, fields);
  return fields;
}

/**
 * 임의의 지점으로 향하는 흐름장 (호위전 거점처럼 「경유지」가 있을 때).
 * 목적지 칸 번호로 캐시한다 — 거점은 몇 개뿐이라 캐시가 금방 채워진다.
 *
 * 결정론: flowFieldOf 와 같은 정수 BFS·고정 순회 순서.
 */
const goalFlowCache = new Map<string, Int32Array>();

export function flowFieldTo(m: MapDef, goalIdx: number): Int32Array | null {
  const mk = m.mask;
  if (!mk || goalIdx < 0 || goalIdx >= mk.cols * mk.rows) return null;
  const key = `${m.id}:${goalIdx}`;
  const hit = goalFlowCache.get(key);
  if (hit) return hit;
  const { cols, rows, data } = mk;
  // 목적지가 벽이면 가장 가까운 걷는 칸을 씨앗으로 삼는다
  const seeds: number[] = [];
  if (data.charCodeAt(goalIdx) === 46) {
    seeds.push(goalIdx);
  } else {
    const gr = (goalIdx / cols) | 0;
    const gc = goalIdx - gr * cols;
    for (let rad = 1; rad <= 12 && seeds.length === 0; rad++) {
      for (let dr = -rad; dr <= rad; dr++) {
        for (let dc = -rad; dc <= rad; dc++) {
          if (dr !== -rad && dr !== rad && dc !== -rad && dc !== rad) continue;
          const r = gr + dr;
          const c = gc + dc;
          if (r < 0 || r >= rows || c < 0 || c >= cols) continue;
          const i = r * cols + c;
          if (data.charCodeAt(i) === 46) seeds.push(i);
        }
      }
    }
  }
  // 흐름장과 같은 규칙 — 벽에 붙은 칸을 비싸게 매겨 길 한복판으로 걷게 한다
  const dist = dialField(m, seeds, hugNearOf(m));
  goalFlowCache.set(key, dist);
  return dist;
}

/**
 * (gx, gy) 로 향하는 다음 칸. 이미 도착했거나 길이 없으면 null.
 * flowStep 의 임의 목적지 버전 — 호위전에서 부대가 마차와 같은 길로 다니게 한다.
 */
export function flowStepTo(
  m: MapDef, gx: number, gy: number, x: number, y: number,
): { x: number; y: number } | null {
  const mk = m.mask;
  if (!mk) return null;
  const field = flowFieldTo(m, maskIndexOf(m, gx, gy));
  if (!field) return null;
  const here = maskIndexOf(m, x, y);
  if (here < 0) return null;
  let cur = field[here]!;
  if (cur < 0) {
    // 벽 안에 있다 — 가장 가까운 길 칸으로 나간다
    let best = -1;
    let bestD = 0;
    const r0 = (here / mk.cols) | 0;
    const c0 = here - r0 * mk.cols;
    for (let rad = 1; rad <= 6 && best < 0; rad++) {
      for (let dr = -rad; dr <= rad; dr++) {
        for (let dc = -rad; dc <= rad; dc++) {
          if (dr !== -rad && dr !== rad && dc !== -rad && dc !== rad) continue;
          const r = r0 + dr;
          const c = c0 + dc;
          if (r < 0 || r >= mk.rows || c < 0 || c >= mk.cols) continue;
          const i = r * mk.cols + c;
          const v = field[i]!;
          if (v < 0) continue;
          if (best < 0 || v < bestD) { best = i; bestD = v; }
        }
      }
    }
    return best >= 0 ? maskCellCenter(m, best) : null;
  }
  if (cur === 0) return null; // 도착
  return followField(m, field, here, cur, x, y);
}

/**
 * 흐름장을 따라가, 지금 자리에서 「충분히 앞선」 첫 칸을 돌려준다.
 *
 * 바로 옆 칸만 보면: 칸 중심이 반 타일 간격이라 유닛이 이미 그 중심을 지나쳐
 * 있으면 「뒤로」 걸어가고 다음 틱엔 다시 앞으로 — 굽은 길목에서 부대가 통째로
 * 제자리 진동하며 멈춰 섰다.
 * 반대로 무조건 여러 칸 앞을 보면: 길이 크게 꺾이는 막다른 골목에서 목표가
 * 벽 너머 먼 점이 되어 유닛이 벽에 붙어 버렸다.
 * 그래서 「MIN_AHEAD 이상 떨어진 첫 칸」까지만 따라간다 — 방향은 안정되고
 * 국소적인 꺾임도 그대로 살아 있다.
 */
const LOOKAHEAD = 6;
const MIN_AHEAD = 750; // FP (0.75타일)

function followField(
  m: MapDef, field: Int32Array, start: number, startDist: number, fromX: number, fromY: number,
): { x: number; y: number } | null {
  const mk = m.mask!;
  let here = start;
  let cur = startDist;
  let last = -1;
  for (let k = 0; k < LOOKAHEAD && cur > 0; k++) {
    const r0 = (here / mk.cols) | 0;
    const c0 = here - r0 * mk.cols;
    let best = -1;
    let bestV = cur;
    for (const n of [
      r0 > 0 ? here - mk.cols : -1,
      r0 < mk.rows - 1 ? here + mk.cols : -1,
      c0 > 0 ? here - 1 : -1,
      c0 < mk.cols - 1 ? here + 1 : -1,
    ]) {
      if (n < 0) continue;
      const v = field[n]!;
      if (v < 0 || v >= bestV) continue;
      bestV = v;
      best = n;
    }
    if (best < 0) break;
    here = best;
    cur = bestV;
    last = best;
    const c = maskCellCenter(m, best);
    const dx = c.x - fromX;
    const dy = c.y - fromY;
    if (dx * dx + dy * dy >= MIN_AHEAD * MIN_AHEAD) break; // 충분히 앞섰다
  }
  return last >= 0 ? maskCellCenter(m, last) : null;
}

/** 격자 인덱스 (마스크가 없으면 -1). */
export function maskIndexOf(m: MapDef, x: number, y: number): number {
  const mk = m.mask;
  if (!mk) return -1;
  const halfH = mapHalfH(m);
  const col = idiv((y + halfH) * mk.cols, halfH * 2);
  const row = idiv(x * mk.rows, m.length);
  if (col < 0 || col >= mk.cols || row < 0 || row >= mk.rows) return -1;
  return row * mk.cols + col;
}

/** 격자 칸 중심의 시뮬 좌표. */
export function maskCellCenter(m: MapDef, idx: number): { x: number; y: number } {
  const mk = m.mask!;
  const row = (idx / mk.cols) | 0;
  const col = idx - row * mk.cols;
  const halfH = mapHalfH(m);
  return {
    x: idiv((row * 2 + 1) * m.length, mk.rows * 2),
    y: idiv((col * 2 + 1) * halfH * 2, mk.cols * 2) - halfH,
  };
}

/**
 * 흐름장을 따라 다음으로 갈 칸의 좌표. 목적지에 닿았거나 길이 없으면 null.
 * team 0 = 진행축 끝으로, team 1 = 시작으로 향한다.
 */
export function flowStep(m: MapDef, team: number, x: number, y: number): { x: number; y: number } | null {
  const fields = flowFieldOf(m);
  if (!fields) return null;
  const field = fields[team === 0 ? 0 : 1]!;
  const mk = m.mask!;
  const here = maskIndexOf(m, x, y);
  if (here < 0) return null;
  let cur = field[here]!;
  if (cur < 0) {
    // 벽 안에 있다 — 가장 가까운 길 칸을 찾아 그리로
    let best = -1;
    let bestD = Infinity;
    const r0 = (here / mk.cols) | 0;
    const c0 = here - r0 * mk.cols;
    for (let rad = 1; rad <= 6 && best < 0; rad++) {
      for (let dr = -rad; dr <= rad; dr++) {
        for (let dc = -rad; dc <= rad; dc++) {
          const r = r0 + dr;
          const c = c0 + dc;
          if (r < 0 || r >= mk.rows || c < 0 || c >= mk.cols) continue;
          const i = r * mk.cols + c;
          if (field[i]! < 0) continue;
          const d = dr * dr + dc * dc;
          if (d < bestD) { bestD = d; best = i; }
        }
      }
    }
    return best >= 0 ? maskCellCenter(m, best) : null;
  }
  if (cur === 0) return null; // 이미 목적지 줄
  // 몇 칸 앞까지 흐름을 따라가 그 자리를 노린다 (바로 옆 칸만 보면 진동한다)
  return followField(m, field, here, cur, x, y);
}

export function isWalkable(m: MapDef, x: number, y: number): boolean {
  const mk = m.mask;
  if (!mk) return true;
  const halfH = mapHalfH(m);
  // FP 좌표 → 격자 인덱스 (정수 연산만 — 결정론)
  const col = idiv((y + halfH) * mk.cols, halfH * 2);
  const row = idiv(x * mk.rows, m.length);
  if (col < 0 || col >= mk.cols || row < 0 || row >= mk.rows) return false;
  return mk.data.charCodeAt(row * mk.cols + col) === 46; // '.'
}

export function mapHalfH(m: MapDef): number {
  let maxAbs = 0;
  for (const [, y] of m.center) {
    const a = y < 0 ? -y : y;
    if (a > maxAbs) maxAbs = a;
  }
  for (const b of m.branches ?? []) {
    const a0 = b.y0 < 0 ? -b.y0 : b.y0;
    const a1 = b.y1 < 0 ? -b.y1 : b.y1;
    if (a0 > maxAbs) maxAbs = a0;
    if (a1 > maxAbs) maxAbs = a1;
  }
  return maxAbs + m.halfW;
}

/** 코리도어 안으로 y 클램프. */
/** x 지점의 메인 레인 반폭 — 초크 구간이면 좁아진다. */
export function laneHalfWAt(m: MapDef, x: number): number {
  for (const ck of m.chokes ?? []) {
    if (x >= ck.x0 && x <= ck.x1) return ck.halfW;
  }
  return m.halfW;
}

export function clampLaneY(m: MapDef, x: number, y: number): number {
  // 격자 마스크가 있는 맵: 지금 자리가 막혔으면 y 를 좌우로 훑어 가장 가까운
  // 통행 가능 지점으로 밀어낸다 (그림에 그려진 길만 밟게 된다).
  if (m.mask) {
    if (isWalkable(m, x, y)) return y;
    const step = idiv(mapHalfH(m) * 2, m.mask.cols); // 격자 한 칸
    for (let k = 1; k <= m.mask.cols; k++) {
      const up = y - step * k;
      if (isWalkable(m, x, up)) return up;
      const dn = y + step * k;
      if (isWalkable(m, x, dn)) return dn;
    }
    return y; // 그 줄 전체가 막혀 있으면 어쩔 수 없다
  }
  const c = laneCenterY(m, x);
  const hw = laneHalfWAt(m, x);
  const lo = c - hw;
  const hi = c + hw;
  let mainY = y < lo ? lo : y > hi ? hi : y;
  // 갈라진 구간: 가운데 지대로는 못 들어간다. 원래 있던 쪽 길로 밀어낸다.
  for (const sp of m.splits ?? []) {
    if (x < sp.x0 || x > sp.x1) continue;
    const rel = mainY - c;
    if (rel > -sp.gap && rel < sp.gap) mainY = rel >= 0 ? c + sp.gap : c - sp.gap;
  }
  // 가지 길: x가 가지 폭 안이고, 가지 클램프 결과가 원래 y에 더 가깝다면 가지에 남는다
  for (const b of m.branches ?? []) {
    const bw = b.halfW ?? m.halfW;
    if (x < b.x - bw || x > b.x + bw) continue;
    const by = y < b.y0 ? b.y0 : y > b.y1 ? b.y1 : y;
    const dMain = mainY > y ? mainY - y : y - mainY;
    const dBr = by > y ? by - y : y - by;
    if (dBr < dMain) return by;
  }
  return mainY;
}

/** 티어별 요구 테크 레벨. 1 = 시작부터, 2 = 중급 테크, 3 = 고급 테크. */
export function techOfTier(tier: string): number {
  if (tier === 'basic' || tier === 'novice') return 1;
  if (tier === 'mid' || tier === 'air') return 2; // 공중 = 초중반 승부수 (대공 체크)
  if (tier === 'final') return 4;                 // 최종 유닛은 4티어를 찍어야 나온다
  return 3; // high, supreme
}

/** 현재 레벨에서 다음 테크업 비용. 최대 레벨이면 undefined. */
export function techUpCost(level: number): number | undefined {
  return MAP.TECH_UP_COST[level - 1];
}

/** 유닛의 실제 요구 테크 (유닛별 오버라이드 > 티어 기본값). */
export function techOfUnit(d: EntityDef): number {
  return d.techReq ?? techOfTier(d.tier);
}

// ── 유닛 정의 ──────────────────────────────────────────────────────────────
// 종족 설정 원본(v0.2): docs/races/{sylvarin,pandemonium,marionetta}.md
// ★ 척도의 수치 변환은 전부 잠정치. 패시브/액티브/업그레이드 체계는 미구현이며
// 일부 능력만 현 엔진 메커니즘(힐/둔화/스플래시/태그 보너스/방어무시/흡혈)으로
// 근사했다. 미구현 시스템에 의존하는 유닛은 로스터에서 잠정 제외:
//   - 실바린 「숲의 묘목」 (숲의 영역/장판 시스템 필요)
//   - 판데모니엄 「레이븐」 (정찰/안개 시스템 필요)

// ── 장판 효과 정의 ─────────────────────────────────────────────────────────
// 장판은 무기의 zone 필드로 생성되고, 매 스텝 범위 내 유닛에게 효과를 준다.
export const ZONE_DEFS: Record<string, {
  /** 적에게 초당 지속피해. */
  readonly dps?: number;
  /** 적 둔화 (안에 있는 동안 유지). */
  readonly slow?: boolean;
  /** 아군 생체 초당 회복 (숲의 영역). */
  readonly healBioPerSec?: number;
  /** 적을 중심으로 끌어당기는 힘 (FP/틱). 사후의 경계. */
  readonly pull?: number;
  /** true 면 공중 유닛에게도 적용된다 (기본 장판은 지상 전용). */
  readonly hitsAir?: boolean;
  /**
   * 밟은 적에게 「독」 상태이상을 건다 (역병 늪).
   *
   * dps 는 장판이 직접 깎는 게 아니라 유닛에게 옮겨 붙는다 — 장판을 벗어나도
   * ticks 동안 계속 닳는다. 그래서 「피하면 그만」이 아니라 힐러가 필요해진다.
   */
  readonly poison?: { readonly dps: number; readonly ticks: number };
}> = {
  thorns: { dps: 8 },                // 가시밭 — 지속피해 전담 (둔화는 포자 구름의 몫)
  spores: { slow: true },            // 포자 구름
  balm: { slow: true, healBioPerSec: 8 }, // 치유 포자 — 적은 둔화, 아군 생체는 회복
  // 역병 늪 (썩어가는 시체) — 장판 자체는 딜이 없고, 밟은 적에게 독을 옮긴다
  venom: { poison: { dps: 6, ticks: seconds(16) } },
  forest: {},                        // 숲의 영역 — 효과는 FOREST_BUFFS (유닛별)
  // 사후의 경계 — 순수 끌어당김 (딜 없음). 지상·공중 모두 빨려온다.
  grave: { pull: 90, hitsAir: true },
  blaze: { dps: 34 },                // 블레이즈 — 불구덩이, 세이지 전용 고화력 장판
  // 은빛 화살비 — 하늘에서 쏟아지므로 공중도 맞는다. dps 는 강화 단계에 따라
  // 시전자가 덮어쓰고(zoneDps), 여기 값은 1단계 기준이다.
  silverrain: { dps: 25, hitsAir: true },
  // 마법의 시전 자국 (효과 없음 — 상태이상·피해는 시전 순간 부여, 이건 그림만)
  quake: {},                         // 어스퀘이크 — 갈라진 땅
  frost: {},                         // 블리자드 — 얼어붙은 땅
  gravity: {},                       // 리버스그라비티 — 중력 마법진
  hellfire: {},                      // 지옥불 — 저주 화염 폭발
  fireburst: {},                     // 화염구 — 착탄 폭발
  // 망자의 만찬 — 넓고 오래가는 저댐 장판 (지상·공중 모두). 중복되지 않는다.
  feast: { dps: 4, hitsAir: true },
  // 검은 폭풍 — 하늘에서 하늘로 부는 깃털바람 (효과 없음, 그림만)
  stormwing: {},
  // ── 지형 해저드 (맵에 처음부터 깔려 있다, team 2 = 양 진영 모두에게 적용) ──
  mud: { slow: true },                 // 진흙길 — 발이 빠져 느려진다
  vinepath: { slow: true, dps: 6 },    // 덩굴길 — 느려지고 가시에 긁힌다
  // 인분의 장막 — 안에 있는 적은 닳고, 공속과 사거리가 줄어든다
  moonveil: { dps: 6, hitsAir: true },
  // 실의 폭풍 — 효과는 스킬이 직접 준다 (그림만)
  threadstorm: {},
  // 메테오 스트라이크 — 하늘에서 운석이 쏟아지는 동안의 자국.
  // 피해·화상·질식은 시전 순간 한 번에 들어가므로 여기 효과는 없다 (그림만).
  meteor: {},
};

